import{z as n,x as o,o as t,c as s,q as e,j as i,D as E,d as r,s as B,S as l}from"./chunks/framework.C8m1ZpeB.js";const b=JSON.parse('{"title":"校准正则化","description":"","frontmatter":{"title":"校准正则化","date":"2026-09-08T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/calibration-regularization.md","filePath":"quant/calibration-regularization.md","lastUpdated":1791063341000}'),p={name:"quant/calibration-regularization.md"};function d(h,a,m,_,u,C){const A=o("Mermaid");return t(),s("div",null,[a[2]||(a[2]=e('<h1 id="校准正则化" tabindex="-1">校准正则化 <a class="header-anchor" href="#校准正则化" aria-label="Permalink to &quot;校准正则化&quot;">​</a></h1><div class="epigraph"><p>能完美穿过每一个报价的局部波动，往往明天就不能用；正则化是在拟合与稳定的对冲比之间做显式权衡。</p><footer>—— 对照 Cont 对模型不确定的框架；局部波动校准的稳定性见 Dupire 实现与 Tikhonov 型罚项的行业实践</footer></div><p><a href="/quant/derivative-model-risk">上一课</a>要求同一香草约束下保留动态区间。本课在<strong>选定的模型类内部</strong>处理反问题：校准 \\(\\min_\\theta\\|P(\\theta)-P_{\\mathrm{mkt}}\\|^2+\\lambda R(\\theta)\\)。主干 <a href="/quant/dupire">Dupire</a> 与 <a href="/quant/sabr-calib">SABR 校准</a> 已写无罚项时怎么做。缺口是 \\(\\lambda R\\)：没有它，翼部噪声会让局部 vol 振荡，希腊值不可用。后课全局优化处理多峰；这里先写罚什么。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>报价有买卖价差、缺失翼部、期限不全。精确插值把噪声当成信号，Dupire 公式对 \\(K\\) 的二阶导放大噪声，局部 vol 出现尖刺，障碍价格和桶风险乱跳。问题是把校准写成不适定反问题：解不唯一或不稳定，必须用正则化——对 \\(\\partial_K\\sigma\\)、对 \\(\\partial_T\\sigma\\)、对参数偏离先验、或对今日参数偏离昨日参数（tikhonov / Kalman / proximal）。</p><p><span class="marginnote">「不适定反问题」翻译：从期权价格反推波动率曲面要连续做两次求导，输入里一点报价噪声，会被求导放大成巨大的输出抖动——好比用不太准的位移数据对时间求两次导去算加速度，误差被平方级放大。正则化就是给解加上「别抖、别离谱」的显式要求。</span></p><p>\\(\\lambda\\) 太大，拟合差，官方模型系统性偏离可交易香草，对冲用错工具。\\(\\lambda\\) 太小，回到振荡。\\(\\lambda\\) 是风险偏好，应随产品（香草做市 vs 障碍簿）分开，不要全行一个数。</p>',7)),(t(),i(l,null,{default:E(()=>[B(A,{id:"mermaid-19",class:"mermaid",graph:"flowchart%20TD%0A%20%20L%7B%22%E6%AD%A3%E5%88%99%E5%8C%96%E5%BC%BA%E5%BA%A6%20%CE%BB%20%E9%80%89%E5%A4%9A%E5%A4%A7%EF%BC%9F%22%7D%0A%20%20L%20--%3E%7C%22%E5%A4%AA%E5%A4%A7%22%7C%20B1%5B%22%E6%8B%9F%E5%90%88%E5%B7%AE%EF%BC%9A%E6%A8%A1%E5%9E%8B%E7%B3%BB%E7%BB%9F%E6%80%A7%E5%81%8F%E7%A6%BB%E5%8F%AF%E4%BA%A4%E6%98%93%E9%A6%99%E8%8D%89%22%5D%0A%20%20B1%20--%3E%20B2%5B%22%E5%AF%B9%E5%86%B2%E7%94%A8%E9%94%99%E5%B7%A5%E5%85%B7%EF%BC%8C%E5%81%9A%E5%B8%82%E6%8A%A5%E4%BB%B7%E5%90%83%E4%BA%8F%22%5D%0A%20%20L%20--%3E%7C%22%E5%A4%AA%E5%B0%8F%22%7C%20S1%5B%22%E7%BF%BC%E9%83%A8%E5%99%AA%E5%A3%B0%E8%A2%AB%E9%80%86%E7%AE%97%E5%AD%90%E6%94%BE%E5%A4%A7%22%5D%0A%20%20S1%20--%3E%20S2%5B%22%E5%B1%80%E9%83%A8%20vol%20%E5%B0%96%E5%88%BA%EF%BC%8C%E6%A1%B6%E9%A3%8E%E9%99%A9%E4%B9%B1%E8%B7%B3%22%5D%0A%20%20B2%20--%3E%20C%5B%22%E6%8C%89%E4%BA%A7%E5%93%81%E5%AE%9A%20%CE%BB%EF%BC%9A%E9%A6%99%E8%8D%89%E5%81%9A%E5%B8%82%E4%B8%8E%E9%9A%9C%E7%A2%8D%E7%B0%BF%E5%88%86%E5%BC%80%22%5D%0A%20%20S2%20--%3E%20C%0A%20%20C%20--%3E%20V%5B%22%E7%94%A8%E5%AF%B9%E5%86%B2%E6%AF%94%E9%9A%94%E6%97%A5%E7%A8%B3%E5%AE%9A%E6%80%A7%EF%BC%88L%20%E6%9B%B2%E7%BA%BF%20%2F%20%E4%BA%A4%E5%8F%89%E9%AA%8C%E8%AF%81%EF%BC%89%E9%80%89%E7%82%B9%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e('<h3 id="罚昨日比罚光滑更像交易" tabindex="-1">罚昨日比罚光滑更像交易 <a class="header-anchor" href="#罚昨日比罚光滑更像交易" aria-label="Permalink to &quot;罚昨日比罚光滑更像交易&quot;">​</a></h3><p>隔日校准若允许参数乱跳，日 PnL 会出现「校准 Theta」：什么都没发生，模型重标定就把价值搬走。对 \\(\\|\\theta_t-\\theta_{t-1}\\|\\) 加罚，等于承认曲面 PCA 的慢因子，让希腊值可对冲。这与完全重拟合「以拟合优度为荣」的研究习惯冲突，交易上前者才对。</p><p><span class="marginnote">「校准 Theta」的数字实例：参数每天自由乱跳的模型，同一组合在无任何行情变化的一夜之间，可以仅因重标定就被平白挪动几十个 bp 的估值；对隔日参数差加罚后，这类「无事生非」的盈亏日大幅减少——罚的本质是把重标定的冲击先计价，再决定要不要接受。</span></p><p><span class="marginnote">买卖价差应进入加权：中间价不是真值，买侧与卖侧内的点权重大，外侧权重小。用中间价做等权 RMSE，会让稀疏翼部绑架 \\(\\theta\\)。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>目标函数用价差加权的价格误差，或加权隐波误差（两者最优 \\(\\theta\\) 不同，要固定一种并报告）。\\(R(\\theta)\\) 选：二阶差分光滑、参数盒约束、相对昨日的二次罚、或 SABR 里对 \\(\\rho,\\nu\\) 的先验。用 L 曲线或交叉验证在「对冲比隔日稳定」上选 \\(\\lambda\\)，而不是在样本内 RMSE 上选。输出：校准残差表 + 参数隔日变化表，两张都进模型风险。</p><p>AAD 提供 \\(\\partial P/\\partial\\theta\\)，使带罚项的 Gauss–Newton 可行。罚项本身的梯度不要漏。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>反问题把高维报价压到低维 \\(\\theta\\) 或压到一个函数 \\(\\sigma(K,T)\\)。无罚时逆算子把高频噪声放大。罚项把解投影到慢子空间，正好与曲面 PCA 的前几个因子对齐。于是正则化不仅是数值稳定，也是承认市场数据的有效维度。</p>',9)),(t(),i(l,null,{default:E(()=>[B(A,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20Mkt%5B%22%E5%B8%A6%E4%BB%B7%E5%B7%AE%E7%9A%84%E6%8A%A5%E4%BB%B7%22%5D%20--%3E%20Loss%5B%22%E5%8A%A0%E6%9D%83%E6%8B%9F%E5%90%88%22%5D%0A%20%20Prior%5B%22%E5%85%89%E6%BB%91%E6%88%96%E9%9A%94%E6%97%A5%E7%BD%9A%22%5D%20--%3E%20R%5B%22%CE%BB%20R%20%CE%B8%22%5D%0A%20%20Loss%20--%3E%20Min%5B%22%E6%A0%A1%E5%87%86%22%5D%0A%20%20R%20--%3E%20Min%0A%20%20Min%20--%3E%20Stab%5B%22%E5%AF%B9%E5%86%B2%E6%AF%94%E9%9A%94%E6%97%A5%E7%A8%B3%E5%AE%9A%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=e('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>正则化不能消灭 Cont 的模型区间：它只在一类模型里选稳定点。换类仍要另报。过度贴近昨日会让模型落后于真正的体制切换，需对 \\(\\lambda\\) 做压力（允许某日重估）。翼部若完全无报价，正则化等于纯先验，障碍价格的模型带应加大，而不是假装校准过了。</p><p><span class="marginnote">常见误区：以为正则化让模型「更准」。它其实是用拟合度换稳定度；若翼部根本没有报价，正则化就退化成纯先验——你以为校准过了，实际只是把先验抄了一遍，障碍期权的价格带必须相应加宽。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>校准是不适定反问题；光滑与隔日罚换稳定对冲比。</li><li>\\(\\lambda\\) 按产品选，用对冲稳定性而不是最小 RMSE。</li><li>买卖价差加权，避免翼部噪声绑架参数。</li><li>出处：Cont, <em>Mathematical Finance</em>, 2006；Tikhonov 正则化的标准处理；Dupire 校准实现中的光滑罚项。</li></ul>',5))])}const D=n(p,[["render",d]]);export{b as __pageData,D as default};
